export function parseKernelCommandKey(
  value: string,
): PantavionKernelCommandKey {
  switch (safeText(value)) {
    case 'run:terminal':
    case 'run:entrypoint':
    case 'run:artifact':
    case 'run:ops':
      return value as PantavionKernelCommandKey;
    default:
      return 'run:readiness';
  }
}

