private layerForFamily(family: PantavionTaxonomyFamily): PantavionTaxonomyLayer {
    switch (family) {
      case 'kernel':
      case 'registry':
        return 'foundation';
      case 'identity':
      case 'memory':
        return 'identity-trust-policy';
      case 'protocol':
        return 'protocol-capability';
      case 'runtime':
      case 'workspace':
      case 'voice':
      case 'resilience':
        return 'runtime';
      case 'admin':
        return 'admin-governance';
      default:
        return 'foundation';
    }
  }

